export type ProviderLogoResolution =
  | { kind: "svg"; key: string; paths: string[]; title: string }
  | { kind: "favicon"; url: string; hostname: string }
  | { kind: "fallback"; icon: "openai" | "anthropic" | "server"; title: string }

export function resolveProviderLogo(
  id?: string | null,
  name?: string | null,
  baseUrl?: string | null,
  apiType?: string | null,
): ProviderLogoResolution {
  const cleanId = (id ?? "").trim().toLowerCase()
  const cleanName = (name ?? "").trim().toLowerCase().replace(/\s+/g, "-")

  // 1. Official mark by id / alias / name.
  const byKey = PROVIDER_LOGO_KEY[cleanId] ?? PROVIDER_LOGO_KEY[cleanName]
  if (byKey && PROVIDER_LOGO_PATHS[byKey]) {
    const p = PROVIDER_LOGO_PATHS[byKey]
    return { kind: "svg", key: byKey, paths: p.paths, title: p.title }
  }
  if (!byKey) {
    const first = cleanName.split("-")[0]
    const byFirst = PROVIDER_LOGO_KEY[first]
    if (byFirst && PROVIDER_LOGO_PATHS[byFirst]) {
      const p = PROVIDER_LOGO_PATHS[byFirst]
      return { kind: "svg", key: byFirst, paths: p.paths, title: p.title }
    }
  }

  // 2. baseUrl hostname keyword match (custom provider pointing at a vendor).
  if (baseUrl) {
    let host = baseUrl.toLowerCase()
    try {
      host = new URL(baseUrl).hostname.toLowerCase()
    } catch {
      // not a URL — use the raw string, keywords still help
    }
    for (const [kw, logo] of DOMAIN_LOGO_KEYWORDS) {
      if (host.includes(kw) && PROVIDER_LOGO_PATHS[logo]) {
        const p = PROVIDER_LOGO_PATHS[logo]
        return { kind: "svg", key: logo, paths: p.paths, title: p.title }
      }
    }
  }

  // 3. Custom endpoint: try the domain favicon, unless it is a private IP / localhost.
  if (baseUrl) {
    try {
      const u = new URL(baseUrl)
      const hostname = u.hostname
      const isPrivate = /^(127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])|localhost|::1)/.test(hostname)
      if (!isPrivate && hostname.includes(".")) {
        return { kind: "favicon", url: `https://www.google.com/s2/favicons?domain=${encodeURIComponent(hostname)}&sz=64`, hostname }
      }
    } catch {
      // not a URL — fall through
    }
  }

  // 4. Modern fallback by apiType, never a letters badge.
  const kind = apiType === "responses" ? "openai" : (cleanId.includes("anthropic") || cleanName.includes("anthropic") ? "anthropic" : "openai")
  return { kind: "fallback", icon: kind, title: name ?? id ?? "Provider" }
}
